#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int N = 105;
vector<int> adj[N];
int color[N], n, m;

bool isBipartite() {
    for (int i = 1; i <= n; i++) {
        if (color[i] == 0) {
            queue<int> q;
            q.push(i);
            color[i] = 1;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) {
                    if (color[v] == 0) {
                        color[v] = 3 - color[u];
                        q.push(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    cin >> n >> m;
    for (int i = 1; i <= m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    if (isBipartite()) {
        cout << "Bipartite graph" << endl;
    } else {
        cout << "Not bipartite" << endl;
    }

    return 0;
}

