int match[N];
bool vis[N];
vector<int> adj[N];
int n, m, k;

bool dfs(int u) {
    for (int v : adj[u]) {
        if (vis[v]) continue;
        vis[v] = true;
        if (match[v] == 0 || dfs(match[v])) {
            match[v] = u;
            return true;
        }
    }
    return false;
}

int hungarian() {
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) vis[j] = false;
        if (dfs(i)) ans++;
    }
    return ans;
}

