#include <iostream>
#include <queue>
using namespace std;

const int N = 205, M = 5005, INF = 1e9;
int head[N], to[M], cap[M], nxt[M], tot = 1;
int vis[N], n, m, s, t;

void addEdge(int u, int v, int w) {
    to[++tot] = v; cap[tot] = w; nxt[tot] = head[u]; head[u] = tot;
    to[++tot] = u; cap[tot] = 0; nxt[tot] = head[v]; head[v] = tot;
}

int dfs(int u, int flow) {
    if (u == t) return flow;
    vis[u] = true;
    for (int i = head[u]; i; i = nxt[i]) {
        int v = to[i];
        if (!vis[v] && cap[i] > 0) {
            int ret = dfs(v, min(flow, cap[i]));
            if (ret > 0) {
                cap[i] -= ret;
                cap[i ^ 1] += ret;
                return ret;
            }
        }
    }
    return 0;
}

int fordFulkerson() {
    int ans = 0, flow;
    while ((flow = dfs(s, INF)) > 0) {
        ans += flow;
        for (int i = 1; i <= n; i++) vis[i] = false;
    }
    return ans;
}

int main() {
    cin >> n >> m >> s >> t;
    for (int i = 1; i <= m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        addEdge(u, v, w);
    }

    int ans = fordFulkerson();

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

const int N = 1005, M = 20005, INF = 1e9;
int head[N], to[M], cap[M], nxt[M], tot = 1;
int d[N], cur[N], n, m, s, t;

void addEdge(int u, int v, int w) {
    to[++tot] = v; cap[tot] = w; nxt[tot] = head[u]; head[u] = tot;
    to[++tot] = u; cap[tot] = 0; nxt[tot] = head[v]; head[v] = tot;
}

bool bfs() {
    for (int i = 1; i <= n; i++) d[i] = 0;
    queue<int> q;
    q.push(s); d[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i; i = nxt[i]) {
            int v = to[i];
            if (!d[v] && cap[i] > 0) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }
    return d[t] > 0;
}

int dfs(int u, int flow) {
    if (u == t) return flow;
    for (int& i = cur[u]; i; i = nxt[i]) {
        int v = to[i];
        if (d[v] == d[u] + 1 && cap[i] > 0) {
            int ret = dfs(v, min(flow, cap[i]));
            if (ret > 0) {
                cap[i] -= ret;
                cap[i ^ 1] += ret;
                return ret;
            }
        }
    }
    return 0;
}

int dinic() {
    int ans = 0, flow;
    while (bfs()) {
        for (int i = 1; i <= n; i++) cur[i] = head[i];
        while ((flow = dfs(s, INF)) > 0) ans += flow;
    }
    return ans;
}

int main() {
    cin >> n >> m >> s >> t;
    for (int i = 1; i <= m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        addEdge(u, v, w);
    }

    int ans = dinic();

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

const int N = 1005, M = 20005, INF = 1e9;
int head[N], to[M], cap[M], cost[M], nxt[M], tot = 1;
int dist[N], pre[N], last[N];
bool vis[N];
int n, m, s, t, maxflow, mincost;

void addEdge(int u, int v, int w, int c) {
    to[++tot] = v; cap[tot] = w; cost[tot] = c; nxt[tot] = head[u]; head[u] = tot;
    to[++tot] = u; cap[tot] = 0; cost[tot] = -c; nxt[tot] = head[v]; head[v] = tot;
}

bool spfa() {
    for (int i = 1; i <= n; i++) dist[i] = INF, vis[i] = false;
    queue<int> q;
    q.push(s); dist[s] = 0; vis[s] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop(); vis[u] = false;
        for (int i = head[u]; i; i = nxt[i]) {
            int v = to[i];
            if (cap[i] > 0 && dist[v] > dist[u] + cost[i]) {
                dist[v] = dist[u] + cost[i];
                pre[v] = u;
                last[v] = i;
                if (!vis[v]) {
                    vis[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return dist[t] < INF;
}

void mcmf() {
    while (spfa()) {
        int flow = INF;
        for (int i = t; i != s; i = pre[i]) {
            flow = min(flow, cap[last[i]]);
        }
        for (int i = t; i != s; i = pre[i]) {
            cap[last[i]] -= flow;
            cap[last[i] ^ 1] += flow;
        }
        maxflow += flow;
        mincost += flow * dist[t];
    }
}

int main() {
    cin >> n >> m >> s >> t;
    for (int i = 1; i <= m; i++) {
        int u, v, w, c;
        cin >> u >> v >> w >> c;
        addEdge(u, v, w, c);
    }

    mcmf();

    cout << maxflow << " " << mincost << endl;

    return 0;
}
